package com.smarthub.plus;
import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.time.*;import java.util.*;
public final class SportsCenterActivity extends HubActivity implements MatchRepository.Listener {
 private MatchRepository repository;private LinearLayout results;private TextView status;private MatchTickerView ticker;private String filter="today",group="",window="day";private LocalDate day=LocalDate.now(ZoneId.of("Asia/Baghdad"));private boolean closed;private final Handler ui=new Handler(Looper.getMainLooper());
 private final Runnable poll=new Runnable(){public void run(){if(closed)return;repository.refresh(day,window,false);ui.postDelayed(this,120000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);repository=MatchRepository.get(this);LinearLayout body=page("IRAQhub · Sports Center",tx("مباريات المصدر فقط · التوقيت Asia/Baghdad · تغطية مجانية محدودة","Source events only · Asia/Baghdad · free coverage is limited"));status=text("",14,false);body.addView(status);LinearLayout first=row();button(first,tx("الكل","All"),()->set("all","","day"));button(first,tx("مباشر","Live"),()->set("live","","day"));button(first,tx("اليوم","Today"),()->{day=LocalDate.now(ZoneId.of("Asia/Baghdad"));set("today","","day");});button(first,tx("القادمة","Upcoming"),()->set("next","","next"));button(first,tx("السابقة","Previous"),()->set("past","","past"));body.addView(first);LinearLayout categories=row();button(categories,"Big 5",()->set("all","big5",window));button(categories,"UCL",()->{group="4480";render(repository.snapshot());});button(categories,tx("العراق","Iraq"),()->set("all","iraq",window));button(categories,tx("دولية","International"),()->set("all","international",window));button(categories,tx("الدوريات المفضلة","Favourite leagues"),this::leagues);body.addView(categories);LinearLayout dates=row();button(dates,"◀ −1 day",()->{day=day.minusDays(1);set("today",group,"day");});button(dates,"+1 day ▶",()->{day=day.plusDays(1);set("today",group,"day");});button(dates,tx("تحديث","Refresh"),()->repository.refresh(day,window,true));button(dates,tx("تقرير التغطية","Coverage report"),this::coverage);body.addView(dates);CheckBox show=check(body,tx("عرض شريط المباريات داخل Infobar","Show match ticker in Infobar"),prefs().getBoolean("sports_ticker",false));show.setOnCheckedChangeListener((v,on)->prefs().edit().putBoolean("sports_ticker",on).apply());ticker=new MatchTickerView(this);body.addView(ticker,new LinearLayout.LayoutParams(-1,dp(82)));results=col();body.addView(results);note(body,tx("TheSportsDB المجاني: حتى 3 مباريات في اليوم لكل بطولة ومباراة واحدة للقادمة/السابقة؛ ليس خدمة Live كاملة. يُضاف OpenLigaDB المجتمعي عندما توجد مطابقة موثّقة للموسم الحالي. عدم توفر تغطية ليس نتيجة صفر–صفر.","TheSportsDB free: up to 3 events/day/league and 1 next/previous event; not a complete live feed. Verified current-season OpenLigaDB data is added when available. Missing coverage never means a 0–0 score."));repository.listen(this);ui.post(poll);}
 private void button(LinearLayout row,String text,Runnable action){Button b=button(text);b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(b,p);}
 private void set(String f,String g,String w){filter=f;group=g;window=w;render(repository.snapshot());repository.refresh(day,w,false);}
 @Override public void update(List<SportsMatch> matches,String message){runOnUiThread(()->{if(closed)return;status.setText(day+" · Baghdad\n"+message);render(matches);});}
 private void render(List<SportsMatch> all){if(results==null)return;List<SportsMatch> visible=new ArrayList<>();for(SportsMatch m:all){LeagueRepository.League l=LeagueRepository.byId(m.leagueId);if(l==null||!repository.selected(l)||!group.isEmpty()&&!group.equals(l.group)&&!group.equals(l.id))continue;LocalDate date=m.kickoff>0?Instant.ofEpochMilli(m.kickoff).atZone(ZoneId.of("Asia/Baghdad")).toLocalDate():null;if(filter.equals("today")&&!day.equals(date)||filter.equals("live")&&(!m.live()||m.cached||System.currentTimeMillis()-m.updatedAt>150000)||filter.equals("next")&&(m.finished()||m.kickoff<System.currentTimeMillis())||filter.equals("past")&&!m.finished())continue;visible.add(m);}ticker.bind(visible);results.removeAllViews();int n=0;for(SportsMatch m:visible){if(n++>=250)break;LinearLayout card=card(results);LinearLayout icons=row();for(String[] team:new String[][]{{m.homeId,m.homeLogo,m.home},{m.awayId,m.awayLogo,m.away}}){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription(team[2]);icons.addView(image,new LinearLayout.LayoutParams(dp(60),dp(54)));TeamLogoManager.bind(this,image,team[0],team[1]);}icons.addView(text(m.home+"   "+m.score()+"   "+m.away,20,true),new LinearLayout.LayoutParams(0,-2,1));card.addView(icons);note(card,m.league+" · "+m.time()+" Baghdad · "+m.state()+"\n"+m.source+" · "+tx("آخر جلب: ","Fetched: ")+java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.of("Asia/Baghdad")).format(Instant.ofEpochMilli(m.updatedAt)));action(card,tx("تفاصيل المباراة","Match details"),()->startActivity(new Intent(this,MatchDetailsView.class).putExtra("match_id",m.id)));}if(visible.isEmpty())note(results,tx("لا توجد مباريات منشورة في هذا المرشح. راجع تقرير التغطية وحالة الاتصال.","No source events in this filter. Check coverage and connection status."));}
 private void leagues(){String[] names=new String[LeagueRepository.ALL.size()];boolean[] selected=new boolean[names.length];for(int i=0;i<names.length;i++){names[i]=LeagueRepository.ALL.get(i).name;selected[i]=repository.selected(LeagueRepository.ALL.get(i));}new android.app.AlertDialog.Builder(this).setTitle(tx("اختيار الدوريات","Select leagues")).setMultiChoiceItems(names,selected,(d,i,on)->prefs().edit().putBoolean("sports_league:"+names[i],on).apply()).setPositiveButton(tx("حفظ","Save"),(d,w)->{render(repository.snapshot());repository.refresh(day,window,false);}).show();}
 private void coverage(){StringBuilder b=new StringBuilder("TheSportsDB v1 shared public key 123 · free limits\nOpenLigaDB ODbL fallback; no guaranteed live coverage\n\n");for(LeagueRepository.League l:LeagueRepository.ALL)b.append(l.name).append(" · ID ").append(l.id.isEmpty()?"unverified / unavailable":l.id).append("\n").append(l.id.isEmpty()?"No verified source mapping":prefs().getString("sports_coverage:"+l.id,"Not yet tested on this device")).append("\n\n");new android.app.AlertDialog.Builder(this).setTitle(tx("تقرير تغطية المصادر","Source coverage report")).setMessage(b.toString()).setPositiveButton("OK",null).show();}
 @Override protected void onDestroy(){closed=true;ui.removeCallbacksAndMessages(null);if(repository!=null)repository.unlisten(this);super.onDestroy();}
}
